+const { topTags } = require('./tags');
+
+function sidebar(tags, topN = 8) {
+  const cloud = topTags(tags, topN).map((t) => t.tag);
+  const recent = tags.slice(0, 5).map((t) => t.tag);
+  return { cloud, recent };
+}
